import {contentHash} from '../../lib/canonical-json.ts';
import type {Workspace} from '../../lib/types.ts';
import type {HistoryClaim,HistoryWorkItem} from '../../lib/history/contracts.ts';
import type {ImmutableMessageBody} from '../../lib/history/citations.ts';
import {validateClaim,type ClaimInputSnapshot} from '../../lib/history/claims.ts';
export const owner='synthetic-understanding-owner',watermark='history:7',now='2026-10-22T00:00:00.000Z';
export const workspace:Workspace={schemaVersion:5,projects:[{id:'project',name:'TAMENNI',description:'',goal:'',color:'teal',priority:'equal',archivedAt:null,repositories:[]},{id:'other-project',name:'Other',description:'',goal:'',color:'orange',priority:'equal',archivedAt:null,repositories:[]}],areas:[{id:'app',projectId:'project',name:'Application',aliases:[],order:0,archivedAt:null},{id:'map',projectId:'project',name:'Map lab',aliases:[],order:1,archivedAt:null},{id:'other-area',projectId:'other-project',name:'Application',aliases:[],order:0,archivedAt:null}],tasks:[],milestones:[],captures:[],activity:[]};
export async function body(id:string,text:string,role:ImmutableMessageBody['message']['role']='user',conversationId=id):Promise<ImmutableMessageBody>{const bytes=new TextEncoder().encode(text);return {ownerId:owner,sourceId:'source',text,requiredContentAvailable:true,message:{id,conversationId,nativeMessageId:id,revisionDigest:await contentHash(bytes),normalizationVersion:'unicode-v1',parentNativeMessageId:null,sequence:0,role,occurredAt:null,observedAt:now,bodyObjectKey:'synthetic:'+id,contentBytes:bytes.length,availability:'complete'}};}
export function claim(message:ImmutableMessageBody,kind:HistoryClaim['kind']='intent',patch:Partial<HistoryClaim>={}):HistoryClaim{return {id:'claim:'+message.message.id,projectId:'project',areaId:'app',kind,text:message.text,basis:'inferred',citations:[{messageRevisionId:message.message.id,revisionDigest:message.message.revisionDigest,start:0,end:Array.from(message.text).length}],supportingEvidence:[],context:{sourceId:message.sourceId,conversationId:message.message.conversationId,messageRevisionId:message.message.id,repositoryIdentity:'github.com/example/app',branch:'main',commit:'a'.repeat(40),basis:'cited_text'},supersedesClaimId:null,extractorVersion:'extractor-v1',...patch};}
export const snapshot=(messages:ImmutableMessageBody[]):ClaimInputSnapshot=>({ownerId:owner,sourceWatermark:watermark,messages,repositories:[],associations:messages.map(m=>({messageRevisionId:m.message.id,projectId:'project',areaId:'app'})),contexts:messages.map(m=>claim(m).context)});
export async function checked(message:ImmutableMessageBody,kind:HistoryClaim['kind']='intent',patch:Partial<HistoryClaim>={}){return validateClaim(claim(message,kind,patch),snapshot([message]),async()=>({supported:true,contradictions:[],requestsWork:kind==='intent'&&message.message.role==='user',completesScope:kind==='implementation'}));}
export function item(id:string,claimIds:string[],patch:Partial<HistoryWorkItem>={}):HistoryWorkItem{return {id,projectId:'project',areaId:'app',workType:'implementation',title:'Android acceptance',state:'open',disposition:'requested',taskId:null,claimIds,supersededById:null,rowRevision:1,...patch};}
